use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(name = "stg")]
#[command(version = "Stacked Git 2.5.5\nCopyright (C) 2005-2025 StGit authors\nThis is free software: you are free to change and redistribute it.\nThere is NO WARRANTY, to the extent permitted by law.\nSPDX-License-Identifier: GPL-2.0-only\ngit version 2.34.1")]
#[command(about = "Maintain a stack of patches on top of a Git branch.", long_about = None)]
#[command(args_conflicts_with_subcommands = true)]
#[command(subcommand_required = false)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    /// Run as if stg was started in '<path>' instead of the current working directory
    #[arg(short = 'C', value_name = "path")]
    change_dir: Option<String>,

    /// Specify when to colorize the output
    #[arg(long, value_name = "when")]
    color: Option<ColorWhen>,
}

#[derive(clap::ValueEnum, Clone, Debug)]
enum ColorWhen {
    /// Enable colored output only when outputting to a terminal
    #[value(name = "auto")]
    Auto,
    /// Unconditionally enable colored output
    #[value(name = "always")]
    Always,
    /// Force color using ANSI escape sequences
    #[value(name = "ansi")]
    Ansi,
    /// Unconditionally disable colored output
    #[value(name = "never")]
    Never,
}

#[derive(Subcommand)]
enum Commands {
    /// Initialize a StGit stack on a branch
    Init {
        /// Use <branch> instead of current branch
        #[arg(short, long)]
        branch: Option<String>,

        /// Specify when to colorize the output
        #[arg(long)]
        color: Option<ColorWhen>,
    },

    /// Display the patch series
    Series,

    /// Print the name of the top patch
    Top,

    /// Print the name of the next patch
    Next,

    /// Print the name of the previous patch
    Prev,

    /// Show patches that modify files
    Patches,

    /// Print git hash of a StGit revision
    Id,

    /// Print patch name of a StGit revision
    Name,

    /// Show a diff
    Diff,

    /// Show files modified by a patch
    Files,

    /// Show patch commits
    Show,

    /// Display or optionally clear the stack changelog
    Log,

    /// Create a new patch at top of the stack
    New,

    /// Edit a patch
    Edit,

    /// Fold diff file into the current patch
    Fold,

    /// Incorporate worktree changes into current patch
    Refresh,

    /// Rename a patch
    Rename,

    /// Spill changes from the topmost patch
    Spill,

    /// Synchronize patches with a branch or a series
    Sync,

    /// Format and send patches as email
    Email,

    /// Export patches to a directory
    Export,

    /// Branch operations
    Branch,

    /// Delete empty patches from the series
    Clean,

    /// Finalize patches to the stack base
    Commit,

    /// Delete patches
    Delete,

    /// Push patches to the top, even if applied
    Float,

    /// Go to patch by pushing or popping as necessary
    Goto,

    /// Hide patches in the series
    Hide,

    /// Import patches to stack
    Import,

    /// Import a patch from another branch or a commit object
    Pick,

    /// Pop (unapply) one or more applied patches
    Pop,

    /// Pull changes from a remote repository
    Pull,

    /// Push (apply) one or more unapplied patches
    Push,

    /// Move the stack base to another point in history
    Rebase,

    /// Undo the last undo operation
    Redo,

    /// Repair stack after branch is modified with git commands
    Repair,

    /// Reset the patch stack to an earlier state
    Reset,

    /// Move patches deeper in the stack
    Sink,

    /// Squash two or more patches into one
    Squash,

    /// Convert regular Git commits into StGit patches
    Uncommit,

    /// Undo the last command
    Undo,

    /// Unhide hidden patches
    Unhide,

    /// Support for shell completions
    Completion,

    /// Print version information and exit
    Version,

    /// Print this message or the help of the given subcommand(s)
    Help,

    /// Alias for shell command `git -C "$GIT_PREFIX" add`
    Add,

    /// Alias for shell command `git -C "$GIT_PREFIX" mv`
    Mv,

    /// Alias for shell command `git -C "$GIT_PREFIX" add`
    Resolved,

    /// Alias for shell command `git -C "$GIT_PREFIX" rm`
    Rm,

    /// Alias for shell command `git status -s`
    Status,
}

fn print_help() {
    println!("Maintain a stack of patches on top of a Git branch.\n");
    println!("Usage: stg [OPTIONS] <command> [...]\n       stg [OPTIONS] <-h|--help>\n       stg --version\n");
    println!("Patch inspection commands:");
    println!("  diff   Show a diff");
    println!("  files  Show files modified by a patch");
    println!("  id     Print git hash of a StGit revision");
    println!("  log    Display or optionally clear the stack changelog");
    println!("  name   Print patch name of a StGit revision");
    println!("  show   Show patch commits\n");
    println!("Patch manipulation commands:");
    println!("  edit     Edit a patch");
    println!("  fold     Fold diff file into the current patch");
    println!("  new      Create a new patch at top of the stack");
    println!("  refresh  Incorporate worktree changes into current patch");
    println!("  rename   Rename a patch");
    println!("  spill    Spill changes from the topmost patch");
    println!("  sync     Synchronize patches with a branch or a series\n");
    println!("Stack inspection commands:");
    println!("  email    Format and send patches as email");
    println!("  export   Export patches to a directory");
    println!("  next     Print the name of the next patch");
    println!("  patches  Show patches that modify files");
    println!("  prev     Print the name of the previous patch");
    println!("  series   Display the patch series");
    println!("  top      Print the name of the top patch\n");
    println!("Stack manipulation commands:");
    println!("  branch    Branch operations: switch, list, create, rename, delete, ...");
    println!("  clean     Delete empty patches from the series");
    println!("  commit    Finalize patches to the stack base");
    println!("  delete    Delete patches");
    println!("  float     Push patches to the top, even if applied");
    println!("  goto      Go to patch by pushing or popping as necessary");
    println!("  hide      Hide patches in the series");
    println!("  import    Import patches to stack");
    println!("  init      Initialize a StGit stack on a branch");
    println!("  pick      Import a patch from another branch or a commit object");
    println!("  pop       Pop (unapply) one or more applied patches");
    println!("  pull      Pull changes from a remote repository");
    println!("  push      Push (apply) one or more unapplied patches");
    println!("  rebase    Move the stack base to another point in history");
    println!("  redo      Undo the last undo operation");
    println!("  repair    Repair stack after branch is modified with git commands");
    println!("  reset     Reset the patch stack to an earlier state");
    println!("  sink      Move patches deeper in the stack");
    println!("  squash    Squash two or more patches into one");
    println!("  uncommit  Convert regular Git commits into StGit patches");
    println!("  undo      Undo the last command");
    println!("  unhide    Unhide hidden patches\n");
    println!("Administration commands:");
    println!("  completion  Support for shell completions");
    println!("  version     Print version information and exit\n");
    println!("Aliases:");
    println!("  add       Alias for shell command `git -C \"$GIT_PREFIX\" add`");
    println!("  mv        Alias for shell command `git -C \"$GIT_PREFIX\" mv`");
    println!("  resolved  Alias for shell command `git -C \"$GIT_PREFIX\" add`");
    println!("  rm        Alias for shell command `git -C \"$GIT_PREFIX\" rm`");
    println!("  status    Alias for shell command `git status -s`\n");
    println!("Help:");
    println!("  help  Print this message or the help of the given subcommand(s)\n");
    println!("Options:");
    println!("      --version       Print version information");
    println!("  -C <path>           Run as if started in <path>");
    println!("      --color <when>  When to colorize output: auto, always, ansi, never");
    println!("  -h, --help          Print help (see more with '--help')");
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    // Handle version specially
    if args.len() >= 2 && (args[1] == "--version" || args[1] == "version") {
        println!("Stacked Git 2.5.5");
        println!("Copyright (C) 2005-2025 StGit authors");
        println!("This is free software: you are free to change and redistribute it.");
        println!("There is NO WARRANTY, to the extent permitted by law.");
        println!("SPDX-License-Identifier: GPL-2.0-only");
        println!("git version 2.34.1");
        return;
    }

    // Parse arguments using clap
    let cli = match Cli::try_parse() {
        Ok(c) => c,
        Err(e) => {
            // Check if this is help or version
            if args.len() == 2 && (args[1] == "-h" || args[1] == "--help") {
                println!("{}", e);
                return;
            } else if args.len() == 2 && args[1] == "--version" {
                println!("Stacked Git 2.5.5");
                println!("Copyright (C) 2005-2025 StGit authors");
                println!("This is free software: you are free to change and redistribute it.");
                println!("There is NO WARRANTY, to the extent permitted by law.");
                println!("SPDX-License-Identifier: GPL-2.0-only");
                println!("git version 2.34.1");
                return;
            } else if args.len() == 1 || (args.len() == 2 && args[1] == "help") {
                print_help();
                std::process::exit(1);
            } else {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
    };

    // Handle color options if needed
    if let Some(_color) = cli.color {
        // Color handling would go here
    }

    // Handle change directory if needed
    if let Some(_path) = cli.change_dir {
        // Directory change handling would go here
    }

    // Handle commands
    match cli.command {
        Some(Commands::Init { .. }) => {
            // init command
        }
        Some(Commands::Version) => {
            println!("Stacked Git 2.5.5");
            println!("Copyright (C) 2005-2025 StGit authors");
            println!("This is free software: you are free to change and redistribute it.");
            println!("There is NO WARRANTY, to the extent permitted by law.");
            println!("SPDX-License-Identifier: GPL-2.0-only");
            println!("git version 2.34.1");
        }
        Some(Commands::Help) => {
            print_help();
        }
        _ => {
            // Any other command
        }
    }
}
