    }

    let mut i = 1;
    let mut _color_arg = None;
    let mut _change_dir = None;

    // Parse global options
    while i < args.len() {
        match args[i].as_str() {
            "--version" => {
                print_version();
                return;
            }
            "-h" | "--help" => {
                if i == 1 {
                    print_help();
                } else {
                    print_full_help();
                }
                return;
            }
            "--color" => {
                if i + 1 < args.len() {
                    _color_arg = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: a value is required for '--color <when>' but none was supplied");
                    eprintln!("  [possible values: auto, always, ansi, never]");
                    eprintln!("");
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(1);
                }
            }
            "-C" => {
                if i + 1 < args.len() {
                    _change_dir = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            _ => break,
        }
    }

    // If no command left
    if i >= args.len() {
        print_help();
        std::process::exit(1);
    }

    let command = &args[i];

    match command.as_str() {
        "help" => {
            print_help();
        }
        "version" => {
            print_version();
        }
        "init" => {
            // Check if help is requested
            for j in (i + 1)..args.len() {
                if args[j] == "-h" || args[j] == "--help" {
                    print_init_help();
                    return;
                }
            }
            // Execute init
        }
        _ => {
            // Check if this is a valid command
            let valid_commands = vec![
                "diff", "files", "id", "log", "name", "show",
                "edit", "fold", "new", "refresh", "rename", "spill", "sync",
                "email", "export", "next", "patches", "prev", "series", "top",
                "branch", "clean", "commit", "delete", "float", "goto", "hide",
                "import", "pick", "pop", "pull", "push", "rebase", "redo",
                "repair", "reset", "sink", "squash", "uncommit", "undo", "unhide",
                "completion", "add", "mv", "resolved", "rm", "status"
            ];

