                eprintln!("error: unrecognized subcommand '{}'", command);

                // Find similar command - always find closest one
                if let Some(similar) = find_closest_command(command, &valid_commands) {
                    eprintln!("\n  tip: a similar subcommand exists: '{}'", similar);
                }

                eprintln!("");
                eprintln!("Usage: stg [OPTIONS] <command> [...]");
                eprintln!("       stg [OPTIONS] <-h|--help>");
                eprintln!("       stg --version");
                eprintln!("");
                eprintln!("For more information, try '--help'.");
                std::process::exit(1);
            }
        }
    }
}

fn find_closest_command(input: &str, valid: &[&str]) -> Option<String> {
    let mut closest = None;
    let mut min_distance = usize::MAX;

    for cmd in valid {
        let dist = levenshtein_distance(input, cmd);
        if dist < min_distance {
            min_distance = dist;
            closest = Some(cmd.to_string());
        }
    }

    closest
}

fn levenshtein_distance(a: &str, b: &str) -> usize {
    let a_len = a.len();
    let b_len = b.len();

    if a_len == 0 {
        return b_len;
    }
    if b_len == 0 {
        return a_len;
    }

    let mut matrix = vec![vec![0; b_len + 1]; a_len + 1];

    for i in 0..=a_len {
        matrix[i][0] = i;
    }
    for j in 0..=b_len {
        matrix[0][j] = j;
    }

    for (i, a_char) in a.chars().enumerate() {
        for (j, b_char) in b.chars().enumerate() {
            let cost = if a_char == b_char { 0 } else { 1 };
            matrix[i + 1][j + 1] = std::cmp::min(
                std::cmp::min(
                    matrix[i][j + 1] + 1,    // deletion
                    matrix[i + 1][j] + 1     // insertion
                ),
                matrix[i][j] + cost          // substitution
            );
        }
    }

    matrix[a_len][b_len]
}
