    println!("Initializing a branch with a StGit stack commits initial, empty stack state for the");
    println!("branch to the repository. Theses stack metadata commits are tracked by the");
    println!("`refs/stacks/<branch>` reference. Updated stack state is committed by each StGit command");
    println!("that modifies the stack. StGit users do not have to do anything with the");
    println!("`refs/stacks/<branch>` ref directly.\n");
    println!("Some StGit commands, such as `stg new` and `stg uncommit`, will automatically initialize");
    println!("the stack, so it is often not necessary to explicitly initialize the stack on a branch.");
    println!("Also, branches created with `stg branch --create` are automatically initialized.\n");
    println!("The branch must already exist and point to a commit before initializing a StGit stack.\n");
    println!("StGit stack metadata can be deinitialized from a branch using `stg branch --cleanup`.");
    println!("See 'stg branch' for more details.\n");
    println!("Usage: stg init [OPTIONS]\n");
    println!("Options:");
    println!("  -b, --branch <branch>");
    println!("          Use <branch> instead of current branch\n");
    println!("      --color <when>");
    println!("          Specify when to colorize the output.");
    println!("          ");
    println!("          `auto` (the default) enables colored output only when outputting to a terminal");
    println!("          or TTY. The `NO_COLOR` environment variable is respected.");
    println!("          ");
    println!("          `always` and `never` unconditionlly enable/disable colored output,");
    println!("          respectively.");
    println!("          ");
    println!("          `ansi` forces color to be output using ANSI escape sequences, even in a");
    println!("          Windows console.\n");
    println!("  -h, --help");
    println!("          Print help (see a summary with '-h')");
}

fn main() {
    let args: Vec<String> = env::args().collect();

    // Default: no args shows help with exit code 1
    if args.len() == 1 {
        print_help();
        std::process::exit(1);
    }

    let mut i = 1;
    let mut _color_arg = None;
    let mut _change_dir = None;

    // Parse global options
    while i < args.len() {
        match args[i].as_str() {
            "--version" => {
                print_version();
                return;
            }
            "-h" | "--help" => {
                if i == 1 {
                    print_help();
                } else {
                    print_full_help();
                }
                return;
            }
            "--color" => {
                if i + 1 < args.len() {
                    _color_arg = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: a value is required for '--color <when>' but none was supplied");
                    eprintln!("  [possible values: auto, always, ansi, never]");
                    eprintln!("");
                    eprintln!("For more information, try '--help'.");
                    std::process::exit(1);
                }
            }
            "-C" => {
                if i + 1 < args.len() {
                    _change_dir = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            _ => break,
        }
    }

    // If no command left
    if i >= args.len() {
        print_help();
        std::process::exit(1);
    }

    let command = &args[i];

    match command.as_str() {
        "help" => {
            print_help();
        }
        "version" => {
            print_version();
        }
        "init" => {
            // Check if help is requested
            for j in (i + 1)..args.len() {
                if args[j] == "-h" || args[j] == "--help" {
                    print_init_help();
                    return;
                }
            }
            // Execute init
        }
        _ => {
            // Check if this is a valid command
            let valid_commands = vec![
                "diff", "files", "id", "log", "name", "show",
                "edit", "fold", "new", "refresh", "rename", "spill", "sync",
                "email", "export", "next", "patches", "prev", "series", "top",
                "branch", "clean", "commit", "delete", "float", "goto", "hide",
                "import", "pick", "pop", "pull", "push", "rebase", "redo",
                "repair", "reset", "sink", "squash", "uncommit", "undo", "unhide",
                "completion", "add", "mv", "resolved", "rm", "status"
            ];

            if valid_commands.contains(&command.as_str()) {
                // Valid command - do nothing for now
            } else {
                // Unknown command
                eprintln!("error: unrecognized subcommand '{}'", command);

                // Find similar command - always find closest one
                if let Some(similar) = find_closest_command(command, &valid_commands) {
                    eprintln!("\n  tip: a similar subcommand exists: '{}'", similar);
                }

                eprintln!("");
                eprintln!("Usage: stg [OPTIONS] <command> [...]");
                eprintln!("       stg [OPTIONS] <-h|--help>");
                eprintln!("       stg --version");
                eprintln!("");
                eprintln!("For more information, try '--help'.");
                std::process::exit(1);
            }
        }
    }
}

fn find_closest_command(input: &str, valid: &[&str]) -> Option<String> {
    let mut closest = None;
    let mut min_distance = usize::MAX;

    for cmd in valid {
        let dist = levenshtein_distance(input, cmd);
        if dist < min_distance {
            min_distance = dist;
            closest = Some(cmd.to_string());
        }
    }

    closest
}

fn levenshtein_distance(a: &str, b: &str) -> usize {
    let a_len = a.len();
    let b_len = b.len();

    if a_len == 0 {
        return b_len;
    }
    if b_len == 0 {
        return a_len;
    }

    let mut matrix = vec![vec![0; b_len + 1]; a_len + 1];

    for i in 0..=a_len {
        matrix[i][0] = i;
    }
    for j in 0..=b_len {
        matrix[0][j] = j;
    }

    for (i, a_char) in a.chars().enumerate() {
        for (j, b_char) in b.chars().enumerate() {
            let cost = if a_char == b_char { 0 } else { 1 };
            matrix[i + 1][j + 1] = std::cmp::min(
                std::cmp::min(
                    matrix[i][j + 1] + 1,    // deletion
                    matrix[i + 1][j] + 1     // insertion
                ),
                matrix[i][j] + cost          // substitution
            );
        }
    }

    matrix[a_len][b_len]
}
